(function(){var loadHandler=window['sl_{74E2B752-FCB1-42CC-BDAB-856BD2AD39CB}'];loadHandler&&loadHandler(5, '<div id="spr0_3e4bd0"><div id="spr1_3e4bd0" class="kern slide"><img id="img2_3e4bd0" src="data:image/png;base64," width="1280px" height="720px" alt="" style="left:0px;top:0px;"/></div><div id="spr2_3e4bd0" class="kern slide"><div id="spr3_3e4bd0" aria-label="Изображение выглядит как мультфильм, Мультфильм, графическая вставка, Анимация  Контент, сгенерированный ИИ, может содержать ошибки." role="group" style="left:1044.396px;top:339.314px;"><div id="spr4_3e4bd0" style="left:-66.156px;"><img id="img0_3e4bd0" src="data:image/png;base64," width="371.962" height="370.923" alt=""/></div></div><div id="spr5_3e4bd0" style="left:42.054px;top:50.637px;"><div style="width:0px;"><span id="txt0_3e4bd0" class="relpos" data-width="108.968750" style="left:9.6px;top:4.475px;">Третье</span> <span id="txt1_3e4bd0" class="relpos" data-width="26.859375" style="left:9.593px;top:4.475px;">:  </span> <span id="txt2_3e4bd0" class="relpos" data-width="523.218750" style="left:9.587px;top:4.475px;">Если  вселенная  так  велика, то</span></div><div style="width:0px;"><span id="txt3_3e4bd0" data-width="660.187500" style="left:9.6px;top:42.875px;">насколько  же Велик Тот, кто её создал?</span></div><div style="width:0px;"><span id="txt4_3e4bd0" data-width="661.578125" style="left:9.6px;top:81.275px;">Бог  не  помещается  внутри вселенной.</span></div><div style="width:0px;"><span id="txt5_3e4bd0" data-width="660.250000" style="left:9.6px;top:119.675px;">Он  -  её  Творец.    Давид   сказал:   &quot;Как</span></div><div style="width:0px;"><span id="txt6_3e4bd0" data-width="664.000000" style="left:9.6px;top:158.075px;">высоко   небо  над  землёй,   так  велика</span></div><div style="width:0px;"><span id="txt7_3e4bd0" data-width="603.375000" style="left:9.6px;top:196.475px;">милость  Господа  к  боящимся  Его&quot; </span></div><div style="width:0px;"><span id="txt8_3e4bd0" data-width="158.580719" style="left:9.6px;top:235.387px;">(Пс. 102:11).</span></div><div style="width:0px;"><span id="txt9_3e4bd0" data-width="957.921875" style="left:9.6px;top:266.875px;">А   пророк   Исайя   восклицает:    &quot;Кто  сотворил   их?  Кто</span></div><div style="width:0px;"><span id="txt10_3e4bd0" data-width="961.515625" style="left:9.6px;top:305.275px;">выводит   воинство   их   счётом?  Он всех  их называет по</span></div><div style="width:0px;"><span id="txt11_3e4bd0" data-width="961.093750" style="left:9.6px;top:343.675px;">имени:  по  множеству  могущества и великой силе у Него</span></div><div style="width:0px;"><span id="txt12_3e4bd0" class="relpos" data-width="379.640625" style="left:9.6px;top:387.313px;">ничто   не   выбывает&quot;  </span> <span id="txt13_3e4bd0" class="relpos" data-width="189.609375" style="left:9.593px;top:393.164px;">(Ис. 40:26).      </span> <span id="txt14_3e4bd0" class="relpos" data-width="384.507812" style="left:9.587px;top:382.021px;">Это   величие    Бога</span> <span id="txt15_3e4bd0" class="relpos" style="left:9.58px;top:382.021px;">.</span></div><div style="width:0px;"><span id="txt16_3e4bd0" data-width="963.921875" style="left:9.6px;top:426.875px;">Он  создал  звёзды.  Он  знает  каждую. Он управляет ими.</span></div><div style="width:0px;"><span id="txt17_3e4bd0" data-width="963.562500" style="left:9.6px;top:465.275px;">Люди иногда поклоняются звёздам или верят в гороскопы.</span></div><div style="width:0px;"><span id="txt18_3e4bd0" data-width="960.640625" style="left:9.6px;top:503.675px;">Но  звёзды - не боги. Они - творение. А Творец -только Бог.</span></div><div style="width:0px;"><span id="txt19_3e4bd0" class="relpos" data-width="509.046875" style="left:9.6px;top:544.694px;">Это мудрость четвёртого дня: </span> <span id="txt20_3e4bd0" class="relpos" data-width="442.186218" style="left:9.593px;top:542.048px;">Бог - Владыка Вселенной</span> <span id="txt21_3e4bd0" class="relpos" style="left:9.587px;top:544.694px;">.</span></div><div style="width:0px;"><span id="txt22_3e4bd0" data-width="625.625000" style="left:9.6px;top:583.675px;">Ничто  не  слишком  велико  для  Него.</span></div></div><div id="spr6_3e4bd0" aria-label="Изображение выглядит как Графика, дизайн, творческий подход  Контент, сгенерированный ИИ, может содержать ошибки." role="group" style="left:818.638px;top:50.637px;"><div id="spr7_3e4bd0"><img id="img1_3e4bd0" src="data:image/png;base64," width="423.75" height="238.5" alt="" style="left:0.129px;top:-0.111px;"/></div></div></div></div>', '{"s":[]}');})();